def detect_RF01(reason, conclusion, context):
    positive_cases = cases_where(conclusion, is_true, context)
    negative_cases = cases_where(conclusion, is_false, context)
    if reason_present_in(reason, positive_cases) and reason_present_in(reason, negative_cases):
        return True
    return False

def detect_RF02(reason, subject, context):
    sapaksa = find_sapaksa(subject, context)
    vipaksa = find_vipaksa(subject, context)
    if reason_present_only_in(reason, subject) and not reason_in(reason, sapaksa) and not reason_in(reason, vipaksa):
        return True
    return False

def detect_RF03(reason, conclusion, context):
    if entails(reason, negate(conclusion), context) and not entails(reason, conclusion, context):
        return True
    return False

def detect_RF04(reason, conclusion, context):
    counter_reasons = find_counter_reasons(conclusion, context)
    for h2 in counter_reasons:
        if strength(h2, negate(conclusion)) >= strength(reason, conclusion):
            if not acknowledges_counter(inference_text, h2):
                return True
    return False

def detect_RF05(subject, context, knowledge_base):
    if not entity_exists(subject, knowledge_base):
        return True
    return False

def detect_RF06(subject, reason_property, context, knowledge_base):
    if entity_exists(subject, knowledge_base):
        if not property_verified(reason_property, subject, knowledge_base):
            return True
    return False

def detect_RF07a(reason, conclusion, inference_text, context):
    upadhis = find_required_qualifiers(reason, conclusion, context)
    if upadhis:
        stated_qualifiers = extract_qualifiers(inference_text)
        missing = [u for u in upadhis if u not in stated_qualifiers]
        if missing:
            return True, missing
    return False, []

def detect_RF07b(reason, conclusion, subject, inference_text, context):
    if general_vyapti_holds(reason, conclusion, context):
        subject_conditions = get_subject_conditions(subject, context)
        defeating = [c for c in subject_conditions if defeats_vyapti(c, reason, conclusion)]
        if defeating and not acknowledged(inference_text, defeating):
            return True, defeating
    return False, []

def detect_RF08(conclusion, context, knowledge_base):
    known_facts = get_relevant_facts(conclusion, knowledge_base)
    for fact in known_facts:
        if contradicts(fact, conclusion) and is_established(fact):
            return True, fact
    return False, None

def detect_RF09(reason, conclusion, context):
    alternative_causes = find_alternative_causes(conclusion, context)
    for k in alternative_causes:
        if fully_explains(k, conclusion) and is_independent(k, reason):
            return True, k
    return False, None

def detect_RF10(claim_content, assertion_context):
    performative_conditions = get_performative_conditions(assertion_context)
    if contradicts(performative_conditions, claim_content):
        return True
    return False

def detect_RF11(reason, conclusion, inference_text, context):
    if all_conditions_present(reason, conclusion, context):
        blockers = find_blockers(conclusion, context)
        for b in blockers:
            if is_active(b, context) and not acknowledged(inference_text, b):
                return True, b
    return False, None

def detect_RF12(conclusion, context):
    vipaksa = find_vipaksa(conclusion, context)
    if not vipaksa and is_universal_claim(conclusion):
        return True
    return False
